-- ============================================================================
-- MemberJunction PostgreSQL Migration — V202607031201__v5.45.x__Preserve_External_Entities_In_CodeGen.sql
-- Generated by the split-and-regenerate pipeline (AST dialect transpile of
-- hand-written DDL; CodeGen objects regenerated natively; metadata re-seeded).
-- NOTE: the two CodeGen-bootstrap routines below (spDeleteUnneededEntityFields,
-- vwEntitiesWithMissingBaseTables) are hand-authored PL/pgSQL — lifted from the
-- committed PG ledger (V202606180947 PG_CodeGen_Cutover and the v5.38 baseline)
-- with the single new external-data-source guard added, mirroring the SS source.
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE SCHEMA IF NOT EXISTS __mj;
SET search_path TO __mj, public;
SET standard_conforming_strings = on;

/* Preserve External Data Source Entities Through CodeGen */
/* External-data-source entities (Entity.ExternalDataSourceID set) have no physical table or view */
/* in the MJ database — their data is proxied live from a remote system. CodeGen's manage-metadata */
/* pass would otherwise treat them as orphaned and prune them on every run:                        */
/*   1. checkAndRemoveMetadataForDeletedTables reads vwEntitiesWithMissingBaseTables and skips     */
/*      external rows with a code-level guard (`if (e.ExternalDataSourceID) continue;`). That guard */
/*      needs the ExternalDataSourceID column present on the row — this migration recreates the     */
/*      `SELECT e.*` view so the column (added in V202607031200) is re-exposed.                     */
/*   2. spDeleteUnneededEntityFields would delete ALL of their EntityField rows. This migration     */
/*      excludes external-data-source entities from that proc — the analogue of its existing        */
/*      "VirtualEntity" exclusion.                                                                   */
/* This is a CodeGen-bootstrap proc (not a user-entity SP) and is re-created in full per the        */
/* convention established by V202604261352 Scoped_EntityField_SPs / V202606180947 PG_CodeGen_Cutover.*/

-- ----------------------------------------------------------------------------
-- spDeleteUnneededEntityFields
--   Removes EntityField rows whose underlying column no longer exists.
--   Lifted from V202606180947 PG_CodeGen_Cutover; the ONLY change vs that
--   version is the added `e."ExternalDataSourceID" IS NULL` guard so external-
--   data-source entities are never pruned (their columns are never in the SQL
--   catalog because their data is remote).
-- ----------------------------------------------------------------------------
DROP FUNCTION IF EXISTS __mj."spDeleteUnneededEntityFields"(TEXT);
DROP FUNCTION IF EXISTS __mj."spDeleteUnneededEntityFields"(TEXT, TEXT);
CREATE OR REPLACE FUNCTION __mj."spDeleteUnneededEntityFields"(
  p_ExcludedSchemaNames TEXT,
  p_EntityIDs TEXT DEFAULT NULL
)
RETURNS TABLE(
  "ID" UUID,
  "EntityID" UUID,
  "Entity" TEXT,
  "Name" TEXT
)
LANGUAGE plpgsql AS $func$
DECLARE
  v_is_scoped BOOLEAN := FALSE;
BEGIN
  DROP TABLE IF EXISTS _del_scope;
  CREATE TEMP TABLE _del_scope AS
    SELECT DISTINCT TRIM(v)::uuid AS entity_id
    FROM unnest(string_to_array(COALESCE(p_EntityIDs, ''), ',')) AS v
    WHERE TRIM(v) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_is_scoped := EXISTS (SELECT 1 FROM _del_scope);

  -- metadata-side fields for in-scope, non-virtual, non-external entities
  DROP TABLE IF EXISTS _del_ef;
  CREATE TEMP TABLE _del_ef AS
  SELECT ef."ID" AS field_id, ef."EntityID" AS entity_id, ef."Entity"::text AS entity_name, ef."Name"::text AS field_name
  FROM __mj."vwEntityFields" ef
  INNER JOIN __mj."vwEntities" e ON ef."EntityID" = e."ID"
  LEFT JOIN unnest(string_to_array(COALESCE(p_ExcludedSchemaNames, ''), ',')) AS ex(v)
    ON e."SchemaName"::text = TRIM(ex.v)
  WHERE e."VirtualEntity" = FALSE
    AND e."ExternalDataSourceID" IS NULL
    AND ex.v IS NULL
    AND (NOT v_is_scoped OR ef."EntityID" IN (SELECT s.entity_id FROM _del_scope s));

  -- actual columns present in the database
  DROP TABLE IF EXISTS _del_actual;
  CREATE TEMP TABLE _del_actual AS
  SELECT sq."EntityID" AS entity_id, sq."FieldName"::text AS field_name
  FROM __mj."vwSQLColumnsAndEntityFields" sq
  WHERE (NOT v_is_scoped OR sq."EntityID" IN (SELECT s.entity_id FROM _del_scope s));

  -- orphans: metadata field with no matching DB column
  DROP TABLE IF EXISTS _del_deleted;
  CREATE TEMP TABLE _del_deleted AS
  SELECT ef.field_id, ef.entity_id, ef.entity_name, ef.field_name
  FROM _del_ef ef
  LEFT JOIN _del_actual actual
    ON ef.entity_id = actual.entity_id AND ef.field_name = actual.field_name
  WHERE actual.field_name IS NULL;

  UPDATE __mj."Entity" ent SET "__mj_UpdatedAt" = now()
  WHERE ent."ID" IN (SELECT DISTINCT d.entity_id FROM _del_deleted d);

  DELETE FROM __mj."EntityFieldValue" efv
  WHERE efv."EntityFieldID" IN (SELECT d.field_id FROM _del_deleted d);

  DELETE FROM __mj."EntityField" delf
  WHERE delf."ID" IN (SELECT d.field_id FROM _del_deleted d);

  RETURN QUERY
  SELECT d.field_id, d.entity_id, d.entity_name, d.field_name FROM _del_deleted d;

  DROP TABLE IF EXISTS _del_deleted;
  DROP TABLE IF EXISTS _del_actual;
  DROP TABLE IF EXISTS _del_ef;
  DROP TABLE IF EXISTS _del_scope;
END;
$func$;

-- ----------------------------------------------------------------------------
-- vwEntitiesWithMissingBaseTables
--   Recreate the view so its `SELECT e.*` re-expands to include the
--   ExternalDataSourceID column added to vwEntities in V202607031200. The
--   definition is otherwise UNCHANGED from the v5.38 baseline — a pure "missing
--   base table" detector. The DO-block wrapper preserves+restores dependent
--   views on CASCADE because the source view's column list changed.
-- ----------------------------------------------------------------------------
DO $do$
DECLARE
  v_target_schema CONSTANT TEXT := '__mj';
  v_target_name CONSTANT TEXT := 'vwEntitiesWithMissingBaseTables';
  vsql CONSTANT TEXT := $vsql$CREATE OR REPLACE VIEW __mj."vwEntitiesWithMissingBaseTables"
AS SELECT
    e.*
FROM
    __mj."vwEntities" e
LEFT JOIN
    information_schema.tables t
ON
    e."SchemaName" = t.table_schema AND
    e."BaseTable" = t.table_name
WHERE
    t.table_name IS NULL$vsql$;
  v_target_oid OID;
  v_dep RECORD;
  v_captured JSONB[] := ARRAY[]::JSONB[];
  v_n INTEGER;
BEGIN
  EXECUTE vsql;
EXCEPTION WHEN invalid_table_definition THEN
  -- Column list changed; need CASCADE. Preserve dependent views first.
  SELECT c.oid INTO v_target_oid
  FROM pg_class c JOIN pg_namespace n ON c.relnamespace = n.oid
  WHERE n.nspname = v_target_schema AND c.relname = v_target_name AND c.relkind = 'v';
  IF v_target_oid IS NOT NULL THEN
    FOR v_dep IN
      WITH RECURSIVE deps AS (
        SELECT c.oid, c.relname AS name, n.nspname AS schema, 1 AS depth
        FROM pg_rewrite r
        JOIN pg_depend d ON d.objid = r.oid
        JOIN pg_class c ON c.oid = r.ev_class
        JOIN pg_namespace n ON c.relnamespace = n.oid
        WHERE d.refobjid = v_target_oid AND d.deptype = 'n'
          AND c.oid <> v_target_oid AND c.relkind = 'v'
        UNION
        SELECT c.oid, c.relname, n.nspname, p.depth + 1
        FROM deps p
        JOIN pg_rewrite r ON TRUE
        JOIN pg_depend d ON d.objid = r.oid AND d.refobjid = p.oid
        JOIN pg_class c ON c.oid = r.ev_class
        JOIN pg_namespace n ON c.relnamespace = n.oid
        WHERE c.relkind = 'v' AND c.oid <> p.oid
      )
      SELECT oid, name, schema, MAX(depth) AS max_depth,
             pg_catalog.pg_get_viewdef(oid, true) AS viewdef
      FROM deps GROUP BY oid, name, schema
      ORDER BY MAX(depth) ASC
    LOOP
      v_captured := v_captured || jsonb_build_object(
        'schema', v_dep.schema, 'name', v_dep.name, 'def', v_dep.viewdef);
    END LOOP;
  END IF;
  EXECUTE format('DROP VIEW IF EXISTS %I.%I CASCADE', v_target_schema, v_target_name);
  EXECUTE vsql;
  IF v_captured IS NOT NULL AND array_length(v_captured, 1) > 0 THEN
    FOR v_n IN 1..array_length(v_captured, 1) LOOP
      BEGIN
        EXECUTE format('CREATE VIEW %I.%I AS %s',
          v_captured[v_n]->>'schema', v_captured[v_n]->>'name', v_captured[v_n]->>'def');
      EXCEPTION WHEN others THEN
        RAISE WARNING 'Could not restore dependent view %.%: %',
          v_captured[v_n]->>'schema', v_captured[v_n]->>'name', SQLERRM;
      END;
    END LOOP;
  END IF;
END;
$do$;

DO $$ BEGIN GRANT SELECT ON __mj."vwEntitiesWithMissingBaseTables" TO "cdp_Developer"; EXCEPTION WHEN others THEN NULL; END $$;
